CREATE TABLE task_comments (id UUID PRIMARY KEY, task_id UUID NOT NULL REFERENCES tasks(id) ON DELETE CASCADE, user_id UUID NOT NULL REFERENCES users(id), content TEXT NOT NULL CHECK(length(content)>0), created_at TIMESTAMPTZ NOT NULL DEFAULT now(), updated_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE task_attachments (id UUID PRIMARY KEY, task_id UUID REFERENCES tasks(id) ON DELETE CASCADE, project_id UUID NOT NULL REFERENCES projects(id) ON DELETE CASCADE, uploaded_by UUID NOT NULL REFERENCES users(id), file_name TEXT NOT NULL, file_path TEXT NOT NULL, file_type TEXT, file_size BIGINT NOT NULL CHECK(file_size>=0), created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE labels (id UUID PRIMARY KEY, workspace_id UUID NOT NULL REFERENCES workspaces(id) ON DELETE CASCADE, name TEXT NOT NULL, color TEXT NOT NULL, UNIQUE(workspace_id,name));
CREATE TABLE task_labels (task_id UUID REFERENCES tasks(id) ON DELETE CASCADE,label_id UUID REFERENCES labels(id) ON DELETE CASCADE,PRIMARY KEY(task_id,label_id));
CREATE TABLE task_dependencies (task_id UUID REFERENCES tasks(id) ON DELETE CASCADE,depends_on_task_id UUID REFERENCES tasks(id) ON DELETE CASCADE,PRIMARY KEY(task_id,depends_on_task_id),CHECK(task_id<>depends_on_task_id));
